import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from "element-plus";
export default {
  __name: 'DeleteContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const form = ref({
      name: ''
    });

    // 打开弹窗
    const openDialog = () => {
      form.value.name = '';
      dialogVisible.value = true;
    };

    // 提交删除请求（使用 PathVariable 拼接 URL）
    const submitDelete = async () => {
      if (!form.value.name) {
        alert('请输入容器名称');
        return;
      }
      try {
        await axios.delete(`http://localhost:8081/container/delete/${encodeURIComponent(form.value.name)}`);
        dialogVisible.value = false;
        ElMessage.success('容器删除成功');
      } catch (error) {
        console.error('删除容器出错：', error);
        ElMessage.error('删除失败：' + (error.response?.data || error.message));
      }
    };

    // 向父组件暴露 openDialog 方法
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      form,
      openDialog,
      submitDelete,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
